contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Bound the amount to a reasonable range and ensure it's > 0
        uint256 initAmount = bound(amount, 1 ether, 100 ether);
        // Fund the contract by sending ETH to its fallback
        vm.deal(address(this), initAmount);
        (bool sent, ) = address(c).call{value: initAmount}("");
        require(sent, "funding failed");
        uint256 balanceBefore = address(c).balance;
        require(balanceBefore > 0, "contract must have balance");

        // Owner calls withdrawAll
        vm.prank(address(c).owner());
        c.withdrawAll();

        uint256 balanceAfter = address(c).balance;
        // The reference contract transfers the full balance, so withdrawAll reduces it to zero.
        // The buggy contract does nothing, leaving the balance unchanged.
        // General rule: after withdrawAll, the balance must be strictly less than before.
        assertTrue(balanceAfter < balanceBefore, "withdrawAll must reduce ETH balance");
    }
}

