import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner = address(0x1234);

    function setUp() public {
        c = new C();
        // owner is set in constructor to msg.sender of setUp (this test contract)
        // we can also prank as the actual owner; but we need a known owner address for assertions.
        // The constructor sets owner = payable(msg.sender) which is address(this) during setUp.
        // We'll use address(this) as owner throughout.
        owner = address(this);
    }

    function testFuzz_property(uint256 amount) public {
        // Restrict amount to be at most the contract's balance after funding.
        // We need enough balance to withdraw.
        uint256 fundAmount = 100 ether;
        vm.deal(address(this), fundAmount);
        // Send some ether to the contract to have a balance.
        // Use sendMoney or fallback. fallback is easiest.
        (bool sent, ) = address(c).call{value: fundAmount}("");
        require(sent, "funding failed");

        // Bound amount to be between 0 and contract balance.
        uint256 contractBalance = address(c).balance;
        amount = bound(amount, 0, contractBalance);

        uint256 balanceBefore = address(c).balance;

        // Owner withdraws amount
        vm.prank(owner);
        c.withdraw(amount);

        uint256 balanceAfter = address(c).balance;

        // Invariant: contract balance must decrease by exactly amount.
        assertTrue(balanceBefore - balanceAfter == amount);
    }
}

